#!/bin/bash
# Resumable: skips any sprite whose flying_src/<name>_flying.png already exists. Safe to rerun after a Codex usage-limit reset.
# Each enemy has its OWN design and palette (no shared recipe).
D="$(cd "$(dirname "$0")" && pwd)"
R="$D/flying_run.sh"
run() { [ -f "$D/flying_src/$1_flying.png" ] || "$R" "$1" "$2" > "$D/flying_src/$1.log" 2>&1; }

run storm_fighter_3 "THUNDERHEAD, a boxy flak gunship. Materials: matte blued gunmetal armour, oily and scuffed; electric-yellow #FFD21F hazard chevrons painted on the side-pod frames; the dorsal cloud-seeder cannon is a drum wrapped in copper induction coils whose muzzle ring of nodes burns white-hot yellow; two top vent stacks with louvres venting hot orange-white; slim rear thrusters burning blue-white plasma; small amber status lights. Palette: gunmetal, electric yellow, copper, blue-white plasma."
run storm_fighter_1 "STORMRAY PUP, a small manta drone. Materials: pale bone-white ceramic shell plates with fine seams and cracks, violet #7B4DFF anodised under-plates, thin cyan lightning veins running through the wings like glowing capillaries, a polished silver spine; the two wing-end pods are small silver turbines with blue plasma thrusters; the tail spear a clean white blade. Palette: bone white, violet, cyan veins, silver."
run storm_fighter_2 "STORMRAY, a swept manta gunship. Materials: weathered rusted iron, flaking orange-brown rust with patches of verdigris, riveted plates and hard welds, glowing amber #FFB020 slits along the wing leading edges like cooling vents, heavy twin engines with white-hot amber exhaust flames, the tail a cyan electric trident that crackles. Palette: rust orange, verdigris, amber glow, electric cyan."
run storm_fighter_4 "TEMPEST ANVIL, a heavy bomber-slab. Materials: dark forged slate-steel armour slab with big bolted plates; its two shoulder towers are huge Tesla coils wrapped in bare polished copper winding, topped with violent cyan-white plasma arcs; copper bus bars and cable runs across the slab; rear gun pods in blackened steel with brass shell ejectors; belly core a cyan-white lens; one blue flame jet at the stern. Palette: slate, copper, cyan-white arcs."
run storm_big "CLOUD WHALE, a huge airship shaped like a whale. Materials: overlapping pearl and bone-white armoured plates stained violet in the seams, brushed silver ribs and ballast cylinders, tail fins and side fins in storm-cloud grey-lavender with pale silver edging; the gill vents glow electric violet-blue #6E5BFF; the snout cannon burns white-blue with arcs; small lantern lights along the spine in warm pale yellow. Palette: pearl white, violet, silver, lavender-grey."
run storm_chaser "CYCLONE DRONE, a four-bladed rotor drone. Materials: the four scythe blades are heat-blued titanium, with the oxide rainbow running gold to violet to deep blue along the edges and a razor-polished leading edge; the rotor hubs are dark ceramic with etched rings; the central pod is gunmetal with a bright white-cyan eye lens; wind-streak scoring on the blades; tiny sodium-orange position lights. Keep the four blades distinct and evenly spaced round the core. Palette: titanium gold-violet-blue, ceramic black, white-cyan eye."
run storm_alien "STATIC MOTE, a ball of lightning in a lattice cage with spired caps. Materials: the cage is aged pewter and tarnished bronze with a verdigris patina, with violet-glass insulator beads on the struts; the spired caps are brass cones; the caged sphere is violet-white plasma with a white-yellow heart and branching yellow-white arcs reaching to the cage; a small blue plasma nozzle at the bottom spire. Palette: pewter, bronze-verdigris, violet plasma, white-yellow arcs."
run storm_rock_islet "CLOUD ISLET, a natural floating island of rock wrapped in storm cloud, carried along by the wind. NO engines, NO jets, NO thrusters, NO flames, NO machinery, NO antenna. Materials: pale weathered sandstone and slate slabs with moss-free bare strata, chunks breaking away, hanging root-like rock spurs below; a thick violet-grey and pale storm-cloud mantle wrapping its upper rim and drifting off it in wisps; thin yellow-white lightning veining through the cloud and rock cracks. Palette: sandstone, slate, violet-grey cloud, electric yellow-white lightning. Keep the silhouette of a wide slab on top tapering to hanging spurs."
run storm_rock_hail "HAILSTONE, a huge natural hailstone tumbling through the storm. NO engines, NO jets, NO thrusters, NO flames, NO collars, NO bands, NO machinery of any kind. Materials: milky glacier-blue crystalline ice with a white frost crust, concentric growth layers visible in chipped facets, deep navy crater shadows, fine radial cracks that glow electric yellow-white with tiny lightning in them. Palette: glacier blue, frost white, navy, electric yellow. Keep the round, cratered boulder silhouette."
run storm_rock_ore "ORE SHARD, a slanted floating crystal ore blade. Materials: faceted amethyst-violet crystal with deep indigo cores, thick gold ore veins and nuggets embedded in the facets, one cyan-lit edge, a small brass hover collar at the trailing tip with an amber jet. Palette: amethyst, gold, cyan edge, brass."
run storm_rock_slag "ANVIL CHUNK, a heavy natural rock chunk tumbling through the storm, shaped like an anvil. NO engines, NO jets, NO thrusters, NO flames, NO riveted plates, NO machinery of any kind. Materials: charcoal-black lightning-fused slate with glassy fulgurite surfaces and angular split faces, teal-green mineral stains, bright sun-yellow lightning veins glowing in the cracks. Palette: charcoal, mineral teal, sun yellow. Keep the anvil-like chunky silhouette."
[ "$(ls "$D"/flying_src/*_flying.png 2>/dev/null | wc -l)" -ge 11 ] && echo done > "$D/flying_src/ALL_DONE"
